package org.evox.spen.compat;
import android.content.Context;import android.graphics.*;import android.view.*;import android.widget.ImageView;import android.os.*;import android.provider.Settings;import android.util.Log;
/** Display the unmodified Samsung framework pointer using existing in-package pen input. */
public final class NativeHoverCursor {
 private static final Handler main=new Handler(Looper.getMainLooper());private static ImageView view;private static WindowManager windows;private static WindowManager.LayoutParams layout;private static boolean shown;private static long last;private static volatile int rawX,rawY;private static volatile boolean visible;private static Context context;
 private static final Runnable paint=()->paint();
 public static void frame(Context c,boolean hovering,boolean touching,int x,int y){context=c;rawX=x;rawY=y;boolean next=hovering&&!touching&&x>=0&&y>=0&&SystemSettings.getInt(c.getContentResolver(),"pen_hovering_pointer",1)!=0;long now=SystemClock.uptimeMillis();if(next!=visible||now-last>=16){visible=next;last=now;main.removeCallbacks(paint);main.post(paint);}}
 public static void probe(Context c){frame(c,true,false,8357,13356);main.postDelayed(()->{Log.i("AirCommandPort","Samsung cursor render diagnostic attached="+(shown&&view!=null&&view.isAttachedToWindow())+" type="+(layout==null?-1:layout.type)+" touchable="+(layout!=null&&(layout.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE)==0));hide();},350);}
 public static void hide(){visible=false;main.removeCallbacks(paint);main.post(paint);}
 private static void paint(){try{
  if(!visible){if(shown){windows.removeView(view);shown=false;Log.i("AirCommandPort","Original Samsung hover pointer detached");}return;}
  if(!Settings.canDrawOverlays(context)){Log.w("AirCommandPort","Hover pointer overlay permission missing");return;}
  if(view==null){windows=(WindowManager)context.getSystemService(Context.WINDOW_SERVICE);view=new ImageView(context);BitmapFactory.Options options=new BitmapFactory.Options();options.inScaled=false;Bitmap bitmap;try(java.io.InputStream in=context.getAssets().open("samsung-spen-hover-pointer.png")){bitmap=BitmapFactory.decodeStream(in,null,options);}if(bitmap==null)throw new IllegalStateException("Original Samsung pointer bitmap absent");view.setImageBitmap(bitmap);int width=Math.max(1,Math.round(bitmap.getWidth()*context.getResources().getDisplayMetrics().densityDpi/480f)),height=Math.max(1,Math.round(bitmap.getHeight()*context.getResources().getDisplayMetrics().densityDpi/480f));layout=new WindowManager.LayoutParams(width,height,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);layout.gravity=Gravity.TOP|Gravity.LEFT;layout.setFitInsetsTypes(0);layout.alpha=0.79f;layout.setTitle("Samsung S Pen hover pointer");view.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
  Display display=windows.getDefaultDisplay();Point size=new Point();display.getRealSize(size);float u=Math.max(0,Math.min(1,rawX/16714f)),v=Math.max(0,Math.min(1,rawY/26712f)),sx=u,sy=v;switch(display.getRotation()){case 1:sx=v;sy=1-u;break;case 2:sx=1-u;sy=1-v;break;case 3:sx=1-v;sy=u;break;}layout.x=Math.round(sx*(size.x-1))-Math.round(9*context.getResources().getDisplayMetrics().density);layout.y=Math.round(sy*(size.y-1))-Math.round(9*context.getResources().getDisplayMetrics().density);
  if(!shown){windows.addView(view,layout);shown=true;Log.i("AirCommandPort","Original Samsung hover pointer attached size="+layout.width+"x"+layout.height);}else windows.updateViewLayout(view,layout);
 }catch(Exception e){Log.e("AirCommandPort","Samsung pointer render failed",e);}}
}
